customCss:
/* ==========================================================================
   1. RESET EXCLUSIVO DE MÁRGENES EXTERNOS (Inter-elementos a 0px)
   ========================================================================== */

/* Ponemos a 0px estrictamente los márgenes superior e inferior de todos los bloques.
   No tocamos el padding para mantener el diseño interno de tablas, listas y cajas de código intacto.
*/
.mu-editor-area div[data-block-id],
.mu-paragraph, 
p,
.markdown-body p,
ul, ol,
.markdown-body ul,
.markdown-body ol,
blockquote,
.mu-blockquote,
.markdown-body blockquote,
.mu-code-block,
.mu-fenced-code,
pre,
.markdown-body pre,
.markdown-body .highlight,
h1, h3, h4, h5, h6,
.mu-heading,
.markdown-body h1,
.markdown-body h3,
table,
.markdown-body table {
    margin-top: 12px !important;
    margin-bottom: 12px !important;
}

h2,
.markdown-body h2 {
    margin-top: 20px !important;
    margin-bottom: 12px !important;
}

/* 2. Cada elemento interno (viñeta) queda perfectamente pegado a los demás */
li,
.markdown-body li,
li p,
.markdown-body li p {
    margin-top: 0px !important;     /* Cero espacio arriba de cada viñeta */
    margin-bottom: 0px !important;  /* Cero espacio abajo de cada viñeta */
    padding-top: 0px !important;
    padding-bottom: 0px !important;
}


/* Forzamos el color gris de tu texto de Glow para párrafos y listas sin alterar su flujo */
.mu-paragraph, 
p,
.markdown-body p,
li,
.markdown-body li {
    line-height: 1.5 !important;
    color: #9c9898 !important;
}

/* Conservamos la sangría izquierda para que las listas sigan siendo legibles jerárquicamente */
ul, ol,
.markdown-body ul,
.markdown-body ol {
    padding-left: 2em !important;
}

/* ==========================================================================
   2. Estilos Cosméticos de Títulos (Colores de tu Glow con márgenes a cero)
   ========================================================================== */

/* H1: Amarillo crema con fondo morado/azul (Glow ANSI 228 sobre 63) */
h1, 
.markdown-body h1 {
    text-align: center !important;
    color: #45f3de !important;            
    background-color: #444444 !important; 
    padding: 2px 8px !important;
    border-radius: 4px !important;
    border-bottom: none !important; /* Quita la línea gris nativa de GH */
}

/* H2: Alineado a la izquierda, color Cian (#45f3de), fondo oscuro (#262626) 
   y línea inferior continua de lado a lado */
h2,
.markdown-body h2 {
    display: block !important;
    text-align: left !important;
    color: #8144e8 !important;            
    /*background-color: #262626 !important; */
    border-bottom: 2px solid #8144e8 !important; 
    padding-top: 0px !important;
    padding-left: 10px !important;
    padding-right: 10px !important;
    padding-bottom: 2px !important; /* Mantiene la separación visual interna sobre el borde */
    border-radius: 4px 4px 0 0 !important;
    font-size: 1.4em !important;
}

/* H3: Color Azul Cielo (Glow #2ac3de) con fondo oscuro (ANSI 235) */
h3,
.markdown-body h3 {
    display: block !important;
    color: #c08ef0 !important;            
    /*background-color: #262626 !important; */
    padding-left: 8px !important;
    padding-right: 8px !important;
    padding-top: 2px !important;
    padding-bottom: 2px !important;
    border-radius: 4px !important;
}

/* ==========================================================================
   3. Formato Inline (Glow) con Reset Seguro para Bloques Grandes
   ========================================================================== */

/* Negritas de tu Glow (#bcbcbc) */
strong, 
.mu-inline-strong,
.markdown-body strong {
    color: #bcbcbc !important;
    font-weight: bold !important;
}

/* Enlaces de tu Glow (#7aa2f7) */
a, 
.mu-inline-link,
.markdown-body a {
    color: #7aa2f7 !important;
    text-decoration: underline !important;
}

/* Estilo morado para todo elemento de código en línea por defecto */
code, 
.mu-inline-code,
.markdown-body code {
    color: #b570f7 !important;            
    background-color: #262626 !important; 
    padding-left: 5px !important;
    padding-right: 5px !important;
    padding-top: 2px !important;
    padding-bottom: 2px !important;
    border-radius: 3px !important;
    font-family: "Symbols Nerd Font Mono", "JetBrains Mono", "Fira Code", "Hack", "Liberation Mono", "Symbols Nerd Font Mono", monospace !important;
}

/* RESET estricto para proteger los bloques grandes (```) y preservar sus rellenos */
.mu-code-block code,
.mu-fenced-code code,
.mu-code-sandbox code,
pre code,
.markdown-body pre code,
.markdown-body .highlight pre,
.CodeMirror-code span,
.CodeMirror-line span {
    color: inherit !important;
    background-color: transparent !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    border-radius: 0 !important;
    font-family: inherit !important;
}
